const res = pm.response.json();

pm.test("Status 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("Envelope sukses + token", () => {
    pm.expect(res.success).to.eql(true);
    pm.expect(res.data.token).to.be.a("string").and.not.empty;
});

pm.test("Token disimpan ke collection variable token", () => {
    pm.collectionVariables.set("token", res.data.token);
    pm.expect(pm.collectionVariables.get("token")).to.eql(res.data.token);
});

pm.test("Email yang di-login punya email_verified_at (bisa akses endpoint auth:sanctum)", () => {
    pm.expect(res.data.user.email_verified_at).to.not.be.null;
});

const res = pm.response.json();

pm.test("Status 201 Created", () => {
    pm.response.to.have.status(201);
});

pm.test("User baru + token dibuat", () => {
    pm.expect(res.success).to.eql(true);
    pm.expect(res.data.user.email).to.eql(pm.request.json().email);
    pm.expect(res.data.token).to.be.a("string").and.not.empty;
});

pm.test("gauth_type manual & email belum terverifikasi", () => {
    pm.expect(res.data.user.gauth_type).to.eql("manual");
    pm.expect(res.data.user.email_verified_at).to.be.null;
});

pm.test("Token disimpan ke collection variable token", () => {
    pm.collectionVariables.set("token", res.data.token);
});

